-- =====================================================================
-- EduAI Pro — 0001 init: extensions, enums, core tables
-- Server-side source of truth. All timestamps are generated by the DB.
-- =====================================================================

create extension if not exists citext;      -- case-insensitive email
create extension if not exists pgcrypto;    -- gen_random_uuid()

-- ---- Enums -----------------------------------------------------------
do $$ begin
  create type public.user_role as enum ('admin', 'instructor', 'student');
exception when duplicate_object then null; end $$;

do $$ begin
  create type public.onboarding_state as enum ('pending', 'complete');
exception when duplicate_object then null; end $$;

-- ---- Profiles (1:1 with auth.users) ---------------------------------
create table if not exists public.profiles (
  id                  uuid primary key references auth.users (id) on delete cascade,
  email               citext not null unique,
  role                public.user_role not null default 'student',
  full_name           text,
  age                 int check (age is null or (age >= 5 and age <= 120)),
  mobile_e164         text check (mobile_e164 is null or mobile_e164 ~ '^\+[1-9][0-9]{7,14}$'),
  college_id          uuid,
  onboarding_complete boolean not null default false,
  onboarding_step     int not null default 1 check (onboarding_step between 1 and 5),
  onboarding_draft    jsonb not null default '{}'::jsonb,
  guardian_consent    boolean not null default false,
  status              text not null default 'active' check (status in ('active', 'suspended')),
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  last_active_at      timestamptz
);

-- ---- Academic taxonomy (admin-managed) ------------------------------
create table if not exists public.colleges (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  slug        text not null unique,
  created_by  uuid references auth.users (id),
  created_at  timestamptz not null default now()
);

create table if not exists public.fields (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  slug        text not null unique,
  created_by  uuid references auth.users (id),
  created_at  timestamptz not null default now()
);

create table if not exists public.subjects (
  id          uuid primary key default gen_random_uuid(),
  name        text not null,
  college_id  uuid not null references public.colleges (id) on delete cascade,
  created_by  uuid references auth.users (id),
  created_at  timestamptz not null default now(),
  unique (college_id, name)
);

-- Fields available at a given college (drives onboarding step 3).
create table if not exists public.college_fields (
  college_id  uuid not null references public.colleges (id) on delete cascade,
  field_id    uuid not null references public.fields (id) on delete cascade,
  primary key (college_id, field_id)
);

alter table public.profiles
  drop constraint if exists profiles_college_fk;
alter table public.profiles
  add constraint profiles_college_fk
  foreign key (college_id) references public.colleges (id) on delete set null;

-- ---- Student selections (onboarding step 3) -------------------------
create table if not exists public.student_fields (
  student_id  uuid not null references public.profiles (id) on delete cascade,
  field_id    uuid not null references public.fields (id) on delete cascade,
  primary key (student_id, field_id)
);

create table if not exists public.student_subjects (
  student_id  uuid not null references public.profiles (id) on delete cascade,
  subject_id  uuid not null references public.subjects (id) on delete cascade,
  primary key (student_id, subject_id)
);

-- ---- Content ---------------------------------------------------------
create table if not exists public.courses (
  id              uuid primary key default gen_random_uuid(),
  title           text not null,
  slug            text,
  description     text,
  short_description text,
  thumbnail       text,
  college_id      uuid references public.colleges (id) on delete set null,
  subject_id      uuid references public.subjects (id) on delete set null,
  instructor_id   uuid references auth.users (id) on delete set null,
  status          text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  visibility      text not null default 'private' check (visibility in ('private', 'students', 'public')),
  created_by      uuid references auth.users (id),
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  deleted_at      timestamptz
);

create table if not exists public.lessons (
  id          uuid primary key default gen_random_uuid(),
  course_id   uuid not null references public.courses (id) on delete cascade,
  position    int not null default 0,
  title       text not null,
  content     jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);

create table if not exists public.questions (
  id          uuid primary key default gen_random_uuid(),
  course_id   uuid references public.courses (id) on delete cascade,
  field_id    uuid references public.fields (id) on delete set null,
  created_by  uuid references auth.users (id),
  body        jsonb not null default '{}'::jsonb,
  created_at  timestamptz not null default now()
);

create table if not exists public.exams (
  id          uuid primary key default gen_random_uuid(),
  course_id   uuid references public.courses (id) on delete cascade,
  title       text,
  config      jsonb not null default '{}'::jsonb,
  created_by  uuid references auth.users (id),
  created_at  timestamptz not null default now()
);

-- ---- Learning records ------------------------------------------------
create table if not exists public.enrollments (
  id          uuid primary key default gen_random_uuid(),
  student_id  uuid not null references public.profiles (id) on delete cascade,
  course_id   uuid not null references public.courses (id) on delete cascade,
  created_at  timestamptz not null default now(),
  unique (student_id, course_id)
);

-- "resume last item" is stored here.
create table if not exists public.progress (
  id              uuid primary key default gen_random_uuid(),
  student_id      uuid not null references public.profiles (id) on delete cascade,
  course_id       uuid references public.courses (id) on delete cascade,
  lesson_id       uuid references public.lessons (id) on delete set null,
  percent         int not null default 0 check (percent between 0 and 100),
  last_item_type  text,
  last_item_id    text,
  last_state      jsonb not null default '{}'::jsonb,   -- answers so far + timer
  updated_at      timestamptz not null default now(),
  unique (student_id, course_id)
);

create table if not exists public.quiz_attempts (
  id            uuid primary key default gen_random_uuid(),
  student_id    uuid not null references public.profiles (id) on delete cascade,
  exam_id       uuid references public.exams (id) on delete set null,
  course_id     uuid references public.courses (id) on delete set null,
  score         int,
  total         int,
  state         jsonb not null default '{}'::jsonb,
  started_at    timestamptz not null default now(),
  submitted_at  timestamptz
);

create table if not exists public.achievements (
  id          uuid primary key default gen_random_uuid(),
  student_id  uuid not null references public.profiles (id) on delete cascade,
  code        text not null,
  earned_at   timestamptz not null default now(),
  unique (student_id, code)
);

-- ---- Activity (append-only) -----------------------------------------
create table if not exists public.activity_events (
  event_id       uuid primary key default gen_random_uuid(),
  user_id        uuid references auth.users (id) on delete set null,
  email          citext,
  role           public.user_role,
  event_type     text not null,
  entity_type    text,
  entity_id      text,
  metadata       jsonb not null default '{}'::jsonb,
  timestamp_utc  timestamptz not null default now(),   -- server-authored
  session_id     uuid,
  device_summary text                                     -- no IP stored
);

create index if not exists activity_events_user_idx on public.activity_events (user_id);
create index if not exists activity_events_time_idx on public.activity_events (timestamp_utc desc);
create index if not exists activity_events_type_idx on public.activity_events (event_type);

create table if not exists public.sessions (
  id               uuid primary key default gen_random_uuid(),
  user_id          uuid not null references auth.users (id) on delete cascade,
  started_at       timestamptz not null default now(),
  ended_at         timestamptz,
  duration_seconds int,
  device_summary   text
);

-- ---- Governance ------------------------------------------------------
create table if not exists public.consents (
  id           uuid primary key default gen_random_uuid(),
  student_id   uuid not null references public.profiles (id) on delete cascade,
  doc_type     text not null,                 -- 'terms' | 'privacy' | 'guardian'
  doc_version  text not null,
  accepted_at  timestamptz not null default now(),
  user_agent   text
);

create table if not exists public.audit_log (
  id            uuid primary key default gen_random_uuid(),
  actor_id      uuid references auth.users (id) on delete set null,
  actor_email   citext,
  action        text not null,
  target_type   text,
  target_id     text,
  before        jsonb,
  after         jsonb,
  timestamp_utc timestamptz not null default now()
);

create table if not exists public.instructor_invites (
  id           uuid primary key default gen_random_uuid(),
  email        citext not null,
  invited_by   uuid not null references auth.users (id),
  token_hash   text not null,
  invited_at   timestamptz not null default now(),
  expires_at   timestamptz not null,
  accepted_at  timestamptz,
  revoked_at   timestamptz
);
create index if not exists instructor_invites_email_idx on public.instructor_invites (email);

create table if not exists public.app_config (
  key         text primary key,
  value       jsonb not null default '{}'::jsonb,
  updated_by  uuid references auth.users (id),
  updated_at  timestamptz not null default now()
);

-- Named permission flags the Admin can inspect/manage.
create table if not exists public.role_permissions (
  role        public.user_role not null,
  permission  text not null,
  primary key (role, permission)
);
